/**
 * App route table. Owned by sprint 0 / F1: fronts do NOT edit this file,
 * each one edits only `features/<its feature>/rutas.ts` (5.5).
 *
 * Order matters: the routes contributed by the features come FIRST, so a front that registers a tab
 * root (for example `/museo` or `/lab`) takes it over from the shell placeholder that follows.
 */
import { Navigate, useLocation, type RouteObject } from 'react-router';
import { rutas as cerebro } from '../features/cerebro/rutas.ts';
import { rutas as creador } from '../features/creador/rutas.ts';
import { rutas as docente } from '../features/docente/rutas.ts';
import { rutas as familia } from '../features/familia/rutas.ts';
import { rutas as grupo } from '../features/grupo/rutas.ts';
import { rutas as holo } from '../features/holo/rutas.ts';
import { rutas as lab } from '../features/lab/rutas.ts';
import { rutas as mundo } from '../features/mundo/rutas.ts';
import { rutas as relevo } from '../features/relevo/rutas.ts';
import { rutas as retos } from '../features/retos/rutas.ts';
import { rutas as tutor } from '../features/tutor/rutas.ts';
import { Ajustes, Clase, Evidencia, Hoy, Reportes } from '../shell/pantallas/Docente.tsx';
import { Cerebro, Lab, Museo, Quipu, Yo } from '../shell/pantallas/Estudiante.tsx';
import { HoloPendiente } from '../shell/pantallas/HoloPendiente.tsx';
import { Unirse } from '../shell/pantallas/Unirse.tsx';
import { Inicio } from './Inicio.tsx';
import { Shell } from './Shell.tsx';
import { mapearUrlVieja } from './urlVieja.ts';

export const rutasDeFeatures: Record<string, RouteObject[]> = {
  relevo,
  lab,
  holo,
  tutor,
  mundo,
  retos,
  docente,
  familia,
  creador,
  grupo,
  cerebro,
};

/** `/display.html?sala=X` typed or bookmarked inside the hash router goes to its new home. */
function RedirigirUrlVieja() {
  const { pathname, search } = useLocation();
  const destino = mapearUrlVieja(new URL(`https://rikuy.local${pathname}${search}`));
  return <Navigate to={destino ? destino.slice(1) : '/'} replace />;
}

const marcadoresDeLaShell: RouteObject[] = [
  { index: true, element: <Inicio /> },
  { path: 'entrar', element: <Unirse /> },
  // Student tabs
  { path: 'museo', element: <Museo /> },
  { path: 'lab', element: <Lab /> },
  { path: 'cerebro', element: <Cerebro /> },
  { path: 'quipu', element: <Quipu /> },
  { path: 'yo', element: <Yo /> },
  // Teacher tabs
  { path: 'hoy', element: <Hoy /> },
  { path: 'clase', element: <Clase /> },
  { path: 'evidencia', element: <Evidencia /> },
  { path: 'reportes', element: <Reportes /> },
  { path: 'ajustes', element: <Ajustes /> },
  // F3 replaces this by registering /holo in features/holo/rutas.ts
  { path: 'holo', element: <HoloPendiente /> },
  // Old multi-page URLs
  ...['display.html', 'control.html', 'panel.html', 'clasico.html'].map((p): RouteObject => ({ path: p, element: <RedirigirUrlVieja /> })),
  { path: '*', element: <Navigate to="/" replace /> },
];

export const rutas: RouteObject[] = [
  {
    path: '/',
    element: <Shell />,
    children: [...Object.values(rutasDeFeatures).flat(), ...marcadoresDeLaShell],
  },
];
